type Row=Record<string,unknown>;
type ImpactSeed={category:ChapterRevisionImpactCategory;targetKind:string;targetId:string;targetVersionId?:string|null;targetChapterDocumentId?:string|null;targetChapterOrder?:number|null;sourceMode:ChapterRevisionImpact["sourceMode"];riskLevel:ChapterRevisionImpact["riskLevel"];reasonChain:string[];recommendedAction:ChapterRevisionAction;allowedActions:ChapterRevisionAction[];activeSourceCount?:number;manualProtected?:boolean;detail?:Record<string,unknown>};
const iso=(value:unknown)=>value instanceof Date?value.toISOString():new Date(String(value)).toISOString();
const nullable=(value:unknown)=>value===null||value===undefined?null:String(value);
const json=(value:unknown)=>JSON.stringify(value===undefined?null:value);

function mapCheckpoint(row:Row):ChapterStableCheckpoint{return{id:String(row.id),bookId:String(row.book_id),chapterDocumentId:String(row.chapter_document_id),bodyVersionId:String(row.body_version_id),sessionId:String(row.session_id),settlementId:String(row.settlement_id),previousCheckpointId:nullable(row.previous_checkpoint_id),chapterOrder:Number(row.chapter_order),summary:(row.summary??{}) as Record<string,unknown>,dependencyHash:String(row.dependency_hash),status:row.status as ChapterStableCheckpoint["status"],createdAt:iso(row.created_at)};}
function mapPreview(row:Row):ChapterRevisionPreview{return{id:String(row.id),bookId:String(row.book_id),sessionId:String(row.session_id),chapterDocumentId:String(row.chapter_document_id),oldBodyVersionId:String(row.old_body_version_id),newBodyVersionId:String(row.new_body_version_id),oldSettlementId:String(row.old_settlement_id),oldCheckpointId:String(row.old_checkpoint_id),restartCheckpointId:nullable(row.restart_checkpoint_id),expectedDocumentRevision:Number(row.expected_document_revision),bodyDiffSummary:row.body_diff_summary as ChapterRevisionPreview["bodyDiffSummary"],impactSummary:(row.impact_summary??{}) as Record<string,number>,snapshotHash:String(row.snapshot_hash),status:row.status as ChapterRevisionPreview["status"],revision:Number(row.revision),createdBy:String(row.created_by),createdAt:iso(row.created_at),updatedAt:iso(row.updated_at)};}
function mapImpact(row:Row):ChapterRevisionImpact{return{id:String(row.id),previewId:String(row.preview_id),sequence:Number(row.sequence),category:row.category as ChapterRevisionImpactCategory,targetKind:String(row.target_kind),targetId:String(row.target_id),targetVersionId:nullable(row.target_version_id),targetChapterDocumentId:nullable(row.target_chapter_document_id),targetChapterOrder:row.target_chapter_order===null?null:Number(row.target_chapter_order),sourceMode:row.source_mode as ChapterRevisionImpact["sourceMode"],riskLevel:row.risk_level as ChapterRevisionImpact["riskLevel"],reasonChain:(row.reason_chain??[]) as string[],recommendedAction:row.recommended_action as ChapterRevisionAction,allowedActions:(row.allowed_actions??[]) as ChapterRevisionAction[],activeSourceCount:Number(row.active_source_count),manualProtected:Boolean(row.manual_protected),detail:(row.detail??{}) as Record<string,unknown>};}
function mapPlan(row:Row,items:Row[]):ChapterRevisionPlan{return{id:String(row.id),previewId:String(row.preview_id),bookId:String(row.book_id),expectedPreviewRevision:Number(row.expected_preview_revision),expectedDocumentRevision:Number(row.expected_document_revision),reason:String(row.reason),status:row.status as ChapterRevisionPlan["status"],summary:(row.summary??{}) as Record<string,number>,revision:Number(row.revision),createdBy:String(row.created_by),confirmedBy:nullable(row.confirmed_by),confirmedAt:row.confirmed_at?iso(row.confirmed_at):null,items:items.map(item=>({id:String(item.id),impactId:String(item.impact_id),selectedAction:item.selected_action as ChapterRevisionAction,decisionSource:item.decision_source as "default"|"user",note:String(item.note),revision:Number(item.revision)}))};}
function stepStatus(row:Row):ChapterRevisionExecution["steps"][number]["status"]{const job=String(row.job_status??"");if(job==="dead_letter")return"dead_letter";if(job==="failed")return"failed";if(job==="cancelled"||job==="cancel_requested")return"cancelled";if(job==="succeeded")return"candidate_ready";if(["leased","running"].includes(job))return"running";if(["queued","retry_scheduled"].includes(job))return"queued";return row.status as ChapterRevisionExecution["steps"][number]["status"];}
function mapExecution(row:Row,steps:Row[]):ChapterRevisionExecution{return{id:String(row.id),planId:String(row.plan_id),previewId:String(row.preview_id),bookId:String(row.book_id),chapterDocumentId:String(row.chapter_document_id),oldBodyVersionId:String(row.old_body_version_id),newBodyVersionId:String(row.new_body_version_id),oldCheckpointId:String(row.old_checkpoint_id),restartCheckpointId:nullable(row.restart_checkpoint_id),adoptionId:String(row.adoption_id),invalidationEventId:nullable(row.invalidation_event_id),status:row.status as ChapterRevisionExecution["status"],currentStep:Number(row.current_step),totalSteps:Number(row.total_steps),revision:Number(row.revision),errorSummary:String(row.error_summary),createdAt:iso(row.created_at),updatedAt:iso(row.updated_at),completedAt:row.completed_at?iso(row.completed_at):null,steps:steps.map(step=>({id:String(step.id),sequence:Number(step.sequence),chapterDocumentId:nullable(step.chapter_document_id),chapterOrder:step.chapter_order===null?null:Number(step.chapter_order),stepKind:step.step_kind as ChapterRevisionExecution["steps"][number]["stepKind"],selectedAction:step.selected_action as ChapterRevisionAction,status:stepStatus(step),backgroundJobId:nullable(step.background_job_id),errorSummary:String(step.error_summary)}))};}

function bodyDiff(oldText:string,newText:string){let prefix=0;while(prefix<oldText.length&&prefix<newText.length&&oldText[prefix]===newText[prefix])prefix++;let suffix=0;while(suffix<oldText.length-prefix&&suffix<newText.length-prefix&&oldText[oldText.length-1-suffix]===newText[newText.length-1-suffix])suffix++;return{oldCharacters:oldText.length,newCharacters:newText.length,changedCharacters:Math.max(oldText.length-prefix-suffix,newText.length-prefix-suffix),commonPrefix:prefix,commonSuffix:suffix};}
function categoryForResource(kind:string):ChapterRevisionImpactCategory{return kind==="planning_version"?"planning":kind==="context_manifest"?"context":kind==="quality_audit_report"?"quality":kind==="ai_task_attempt"?"ai_run":kind.includes("knowledge")?"knowledge":kind.includes("state")?"character_state":"other";}
function impactKey(seed:ImpactSeed){return`${seed.targetKind}:${seed.targetId}:${seed.targetVersionId??""}`;}
async function registerResource(client:PoolClient,kind:string,stableId:string,versionId:string){return String((await client.query("SELECT new_design.register_dependency_resource($1,$2,$3) id",[kind,stableId,versionId])).rows[0].id);}
async function generationRows(client:PoolClient,bookId:string,sourceIds:string[]){return(await client.query(`WITH RECURSIVE walk(resource_id,depth,path) AS (
  SELECT source.id,0,ARRAY[source.id] FROM new_design.dependency_resources source WHERE source.id=ANY($2::uuid[])
  UNION ALL SELECT edge.derived_resource_id,walk.depth+1,walk.path||edge.derived_resource_id FROM walk JOIN new_design.dependency_edges edge ON edge.source_resource_id=walk.resource_id AND edge.book_id=$1 AND edge.status='active' WHERE NOT edge.derived_resource_id=ANY(walk.path) AND walk.depth<99
) SELECT DISTINCT ON(resource.id) resource.id,resource.resource_kind,resource.stable_object_id,resource.exact_version_id,resource.content_hash,COALESCE(state.revision,0) state_revision,COALESCE(state.state,'fresh') state,walk.depth
FROM walk JOIN new_design.dependency_resources resource ON resource.id=walk.resource_id LEFT JOIN ${dependencyResourceStateRows} state ON state.resource_id=resource.id ORDER BY resource.id,walk.depth`,[bookId,sourceIds])).rows.map(row=>({id:String(row.id),resourceKind:String(row.resource_kind),stableObjectId:String(row.stable_object_id),exactVersionId:String(row.exact_version_id),contentHash:String(row.content_hash),stateRevision:Number(row.state_revision),state:String(row.state),depth:Number(row.depth)}));}

export async function createChapterRevisionPreview(sessionId:string,input:{expectedDocumentRevision:number;idempotencyKey:string;createdBy?:string}):Promise<ChapterRevisionWorkspace>{
  const pool=await getNewDesignPool(),prior=(await pool.query(`SELECT id FROM ${chapterRevisionPreviewRows} chapter_revision_preview_record WHERE book_id=(SELECT book_id FROM ${chapterAdoptionSessionRows} chapter_adoption_session_record WHERE id=$1) AND idempotency_key=$2`,[sessionId,input.idempotencyKey])).rows[0];if(prior){await assertRevisionOriginal(pool,'chapter_revision_preview',String(prior.id),{sessionId,...input,createdBy:input.createdBy??'user'});return getChapterRevisionWorkspace(String(prior.id));}const ready=(await pool.query(`SELECT id,expected_document_revision FROM ${chapterRevisionPreviewRows} chapter_revision_preview_record WHERE session_id=$1 AND status='ready' ORDER BY created_at DESC LIMIT 1`,[sessionId])).rows[0];if(ready&&Number(ready.expected_document_revision)===input.expectedDocumentRevision){await assertRevisionOriginal(pool,'chapter_revision_preview',String(ready.id),{sessionId,...input,createdBy:input.createdBy??'user'});return getChapterRevisionWorkspace(String(ready.id));}
  const client=await pool.connect(),previewId=randomUUID(),actor=input.createdBy??"user";
  let committing=false;try{await client.query("BEGIN");await lockStoryRecords(client);await requireCardWorkflowTypes(client,['chapter_revision_preview','chapter_revision_plan','chapter_revision_execution','chapter_revision_event'],true);const repeated=await readRevisionOriginal(client,'chapter_revision_preview','chapter_adoption_session',sessionId,{sessionId,...input,createdBy:actor});if(repeated){await client.query('ROLLBACK');return getChapterRevisionWorkspace(String(repeated.id));}
    const session=assertFound((await client.query(`SELECT session.*,document.revision document_revision,document.adopted_version_id,document.logical_order FROM ${chapterAdoptionSessionRows} session JOIN new_design.chapter_documents document ON document.id=session.chapter_document_id WHERE session.id=$1 FOR UPDATE OF session,document`,[sessionId])).rows[0],"换稿会话不存在。");
    if(session.status!=="impact_review_required")throw new NewDesignError("该章节没有待预览的换稿影响。",409);
    if(Number(session.document_revision)!==input.expectedDocumentRevision)throw new NewDesignError("章节正文已变化，请重新进入换稿流程。",409);
    if(String(session.adopted_version_id)!==String(session.prior_body_version_id))throw new NewDesignError("当前采用正文与预览起点不一致。",409);
    const activePreview=(await client.query(`SELECT id,expected_document_revision FROM ${chapterRevisionPreviewRows} chapter_revision_preview_record WHERE session_id=$1 AND status='ready' ORDER BY created_at DESC LIMIT 1 FOR UPDATE`,[sessionId])).rows[0];if(activePreview){if(Number(activePreview.expected_document_revision)===input.expectedDocumentRevision){await assertRevisionOriginal(client,'chapter_revision_preview',String(activePreview.id),{sessionId,...input,createdBy:actor});await client.query("ROLLBACK");return getChapterRevisionWorkspace(String(activePreview.id));}await updateRevisionRecords(client, 'chapter_revision_preview', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('expired')::text,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz) AS record_patch FROM ${chapterRevisionPreviewRows} record WHERE id=$1 FOR UPDATE OF record`, [activePreview.id], ["id"]);}
    const checkpoint=assertFound((await client.query(`SELECT * FROM ${chapterStableCheckpointRows} chapter_stable_checkpoint_record WHERE chapter_document_id=$1 AND body_version_id=$2 AND status='stable' ORDER BY created_at DESC LIMIT 1 FOR UPDATE`,[session.chapter_document_id,session.prior_body_version_id])).rows[0],"当前正文没有稳定检查点，不能执行旧章换稿。");
    const restart=(await client.query(`SELECT * FROM ${chapterStableCheckpointRows} chapter_stable_checkpoint_record WHERE book_id=$1 AND chapter_order<$2 AND status='stable' ORDER BY chapter_order DESC LIMIT 1`,[session.book_id,session.logical_order])).rows[0];
    const bodies=await client.query("SELECT id,content FROM new_design.chapter_body_versions WHERE id=ANY($1::uuid[])",[[session.prior_body_version_id,session.body_version_id]]),oldBody=assertFound(bodies.rows.find(row=>String(row.id)===String(session.prior_body_version_id)),"旧正文不存在。"),newBody=assertFound(bodies.rows.find(row=>String(row.id)===String(session.body_version_id)),"候选正文不存在。");
    const oldBodyResource=await registerResource(client,"chapter_body_version",String(session.chapter_document_id),String(session.prior_body_version_id)),newBodyResource=await registerResource(client,"chapter_body_version",String(session.chapter_document_id),String(session.body_version_id)),settlementResource=await registerResource(client,"chapter_settlement",String(session.chapter_document_id),String(checkpoint.settlement_id)),generation=await generationRows(client,String(session.book_id),[oldBodyResource,settlementResource]);
    const seeds=new Map<string,ImpactSeed>(),add=(seed:ImpactSeed)=>{if(!seeds.has(impactKey(seed)))seeds.set(impactKey(seed),seed);};
    const facts=await client.query(`SELECT fact.id,fact.predicate,fact.value_json,fact.status,evidence.id evidence_id,(SELECT count(*) FROM ${canonicalFactEvidenceRows} all_evidence WHERE all_evidence.fact_id=fact.id AND all_evidence.stale_at IS NULL) active_sources,mark.protection_kind FROM ${canonicalFactEvidenceRows} evidence JOIN new_design.text_anchors anchor ON anchor.id=evidence.chapter_text_anchor_id JOIN ${canonicalFactRows} fact ON fact.id=evidence.fact_id LEFT JOIN ${chapterRevisionProtectionMarkRows} mark ON mark.book_id=fact.book_id AND mark.target_kind='canonical_fact' AND mark.target_id=fact.id WHERE anchor.body_version_id=$1 AND evidence.stale_at IS NULL`,[session.prior_body_version_id]);
    for(const row of facts.rows){const protectedKind=nullable(row.protection_kind),shared=Number(row.active_sources)>1,sourceMode=protectedKind==="manual_lock"?"manual_locked":protectedKind?"manual_correction":shared?"shared":"exclusive";add({category:"fact",targetKind:"canonical_fact",targetId:String(row.id),sourceMode,riskLevel:sourceMode.startsWith("manual")?"critical":"high",reasonChain:["旧正文是这条事实的证据来源。",shared?"这条事实仍有其他有效证据。":"撤销旧证据后没有其他有效来源。"],recommendedAction:sourceMode.startsWith("manual")?"keep_manual_correction":shared?"mark_stale":"auto_recompute",allowedActions:sourceMode.startsWith("manual")?["keep_manual_correction","review_manually"]:["auto_recompute","review_manually","mark_stale","keep_manual_correction"],activeSourceCount:Number(row.active_sources),manualProtected:Boolean(protectedKind),detail:{title:String(row.predicate),value:row.value_json,evidenceId:String(row.evidence_id)}});}
    const knowledge=await client.query(`SELECT change.id,change.proposal_id,change.holder_key,change.stance,item.risk_level,mark.protection_kind FROM ${knowledgeStateChangeRows} change JOIN ${knowledgeStateProposalVersionRows} version ON version.id=change.proposal_version_id LEFT JOIN new_design.chapter_settlement_items item ON item.knowledge_proposal_id=change.proposal_id LEFT JOIN ${chapterRevisionProtectionMarkRows} mark ON mark.book_id=change.book_id AND mark.target_kind='knowledge_state_change' AND mark.target_id=change.id WHERE version.body_version_id=$1 AND change.status='active'`,[session.prior_body_version_id]);
    for(const row of knowledge.rows){const protectedKind=nullable(row.protection_kind),sourceMode=protectedKind==="manual_lock"?"manual_locked":protectedKind?"manual_correction":"exclusive";add({category:"knowledge",targetKind:"knowledge_state_change",targetId:String(row.id),sourceMode,riskLevel:(row.risk_level??"high") as ChapterRevisionImpact["riskLevel"],reasonChain:["角色所知由旧正文中的信息获得。","正文切换后需要重新确认角色是否仍获得该信息。"],recommendedAction:protectedKind?"keep_manual_correction":"auto_recompute",allowedActions:protectedKind?["keep_manual_correction","review_manually"]:["auto_recompute","review_manually","mark_stale","keep_manual_correction"],manualProtected:Boolean(protectedKind),detail:{title:`${row.holder_key} · ${row.stance}`,proposalId:String(row.proposal_id)}});}
    const states=await client.query(`SELECT change.id,change.proposal_id,change.subject_kind,change.subject_id,change.state_key,item.category,item.title,item.risk_level,mark.protection_kind FROM ${stateChangeRows} change LEFT JOIN new_design.chapter_settlement_items item ON item.state_proposal_id=change.proposal_id LEFT JOIN ${chapterRevisionProtectionMarkRows} mark ON mark.book_id=change.book_id AND mark.target_kind='state_change' AND mark.target_id=change.id WHERE change.settlement_id=$1 AND change.status='active'`,[checkpoint.settlement_id]);
    for(const row of states.rows){const category=(["character_state","relationship","prop","event","foreshadow"].includes(String(row.category))?String(row.category):"character_state") as ChapterRevisionImpactCategory,protectedKind=nullable(row.protection_kind),sourceMode=protectedKind==="manual_lock"?"manual_locked":protectedKind?"manual_correction":"exclusive";add({category,targetKind:"state_change",targetId:String(row.id),sourceMode,riskLevel:(row.risk_level??"high") as ChapterRevisionImpact["riskLevel"],reasonChain:["这项变化由旧章节结算产生。","换稿后需要重新核对变化是否仍成立。"],recommendedAction:protectedKind?"keep_manual_correction":"auto_recompute",allowedActions:protectedKind?["keep_manual_correction","review_manually"]:["auto_recompute","review_manually","mark_stale","keep_manual_correction"],manualProtected:Boolean(protectedKind),detail:{title:String(row.title??row.state_key),proposalId:String(row.proposal_id),subjectKind:String(row.subject_kind),subjectId:String(row.subject_id)}});}
    const later=await client.query("SELECT id,logical_order,title,adopted_version_id FROM new_design.chapter_documents WHERE book_id=$1 AND logical_order>$2 AND status='active' ORDER BY logical_order,id",[session.book_id,session.logical_order]);
    for(const row of later.rows)add({category:"later_body",targetKind:"chapter_body",targetId:String(row.id),targetVersionId:nullable(row.adopted_version_id),targetChapterDocumentId:String(row.id),targetChapterOrder:Number(row.logical_order),sourceMode:"downstream_body",riskLevel:"critical",reasonChain:[`第 ${session.logical_order} 章采用正文将被替换。`,`第 ${row.logical_order} 章可能引用旧事实或旧状态。`],recommendedAction:"review_manually",allowedActions:["review_manually","mark_stale"],detail:{title:String(row.title)}});
    for(const resource of generation.filter(item=>item.depth>0)){const category=categoryForResource(resource.resourceKind);add({category,targetKind:"dependency_resource",targetId:resource.id,targetVersionId:resource.exactVersionId,sourceMode:"derived_cache",riskLevel:resource.resourceKind==="chapter_body_version"?"high":"medium",reasonChain:["该内容引用了旧章节的正文、结算或派生结果。",`依赖路径深度：${resource.depth}。`],recommendedAction:"auto_recompute",allowedActions:["auto_recompute","review_manually","mark_stale","defer"],detail:{title:resource.resourceKind,resourceKind:resource.resourceKind,stableObjectId:resource.stableObjectId}});}
    add({category:"graph_index",targetKind:"graph_projection",targetId:String(session.book_id),sourceMode:"derived_cache",riskLevel:"low",reasonChain:["人物、事件和关系图来自正式资料投影。","来源切换后需要排队重建。"],recommendedAction:"auto_recompute",allowedActions:["auto_recompute","mark_stale","defer"],detail:{title:"关系与事件图"}});
    add({category:"semantic_index",targetKind:"semantic_index",targetId:String(session.book_id),sourceMode:"derived_cache",riskLevel:"low",reasonChain:["语义检索索引来自正文与正式资料。","来源切换后需要排队刷新。"],recommendedAction:"auto_recompute",allowedActions:["auto_recompute","mark_stale","defer"],detail:{title:"语义检索索引"}});
    const diff=bodyDiff(String(oldBody.content),String(newBody.content)),impactSummary=Object.fromEntries([...seeds.values()].reduce((map,seed)=>map.set(seed.category,(map.get(seed.category)??0)+1),new Map<string,number>())),snapshotHash=stableHash({sessionId,documentRevision:session.document_revision,oldBodyVersionId:session.prior_body_version_id,newBodyVersionId:session.body_version_id,checkpointId:checkpoint.id,restartCheckpointId:restart?.id??null,generation,diff,impacts:[...seeds.values()]});
    await insertRevisionRecords(client, 'chapter_revision_preview', `SELECT ($1)::uuid AS id,($2)::uuid AS book_id,($3)::uuid AS session_id,($4)::uuid AS chapter_document_id,($5)::uuid AS old_body_version_id,($6)::uuid AS new_body_version_id,($7)::uuid AS old_settlement_id,($8)::uuid AS old_checkpoint_id,($9)::uuid AS restart_checkpoint_id,($10)::integer AS expected_document_revision,($11::jsonb)::jsonb AS dependency_generation,($12::jsonb)::jsonb AS body_diff_summary,($13::jsonb)::jsonb AS impact_summary,($14)::char(64) AS snapshot_hash,('ready')::text AS status,(1)::integer AS revision,($15)::text AS idempotency_key,($16)::text AS created_by,(now())::timestamptz AS created_at,(now())::timestamptz AS updated_at, ($17::jsonb)::jsonb AS request_input,($18)::text AS request_hash`, [previewId,session.book_id,sessionId,session.chapter_document_id,session.prior_body_version_id,session.body_version_id,checkpoint.settlement_id,checkpoint.id,restart?.id??null,input.expectedDocumentRevision,json(generation),json(diff),json(impactSummary),snapshotHash,input.idempotencyKey,actor,json({sessionId,...input,createdBy:actor}),stableHash({sessionId,...input,createdBy:actor})], [["id"],["book_id","idempotency_key"]]);
    let sequence=0;for(const seed of seeds.values())await insertRevisionRecords(client, 'chapter_revision_impact', `SELECT ($1)::uuid AS id,($2)::uuid AS preview_id,($3)::integer AS sequence,($4)::text AS category,($5)::text AS target_kind,($6)::uuid AS target_id,($7)::uuid AS target_version_id,($8)::uuid AS target_chapter_document_id,($9)::integer AS target_chapter_order,($10)::text AS source_mode,($11)::text AS risk_level,($12::jsonb)::jsonb AS reason_chain,($13)::text AS recommended_action,($14)::text[] AS allowed_actions,($15)::integer AS active_source_count,($16)::boolean AS manual_protected,($17::jsonb)::jsonb AS detail,(now())::timestamptz AS created_at`, [randomUUID(),previewId,++sequence,seed.category,seed.targetKind,seed.targetId,seed.targetVersionId??null,seed.targetChapterDocumentId??null,seed.targetChapterOrder??null,seed.sourceMode,seed.riskLevel,json(seed.reasonChain),seed.recommendedAction,seed.allowedActions,seed.activeSourceCount??1,seed.manualProtected??false,json(seed.detail??{})], [["id"],["preview_id","sequence"],["preview_id","target_kind","target_id","target_version_id"]]);
    await insertRevisionRecords(client, 'chapter_revision_event', `SELECT ($1)::uuid AS id,($2)::uuid AS preview_id,(NULL)::uuid AS plan_id,(NULL)::uuid AS execution_id,('preview_created')::text AS event_kind,($3)::text AS actor,($4)::text AS idempotency_key,($5::jsonb)::jsonb AS detail,(now())::timestamptz AS created_at`, [randomUUID(),previewId,actor,input.idempotencyKey,json({impactCount:seeds.size,oldBodyResource,newBodyResource,settlementResource})], [["id"]]);
    committing=true;await client.query("COMMIT");return getChapterRevisionWorkspace(previewId);
  }catch(error){throw await revisionFailure(client,error,committing);}finally{client.release();}
}

export async function saveChapterRevisionPlan(previewId:string,input:{expectedPreviewRevision:number;expectedDocumentRevision:number;reason:string;idempotencyKey:string;createdBy?:string;items:Array<{impactId:string;selectedAction:ChapterRevisionAction;note?:string}>}):Promise<ChapterRevisionWorkspace>{
  const pool=await getNewDesignPool(),prior=(await pool.query(`SELECT id FROM ${chapterRevisionPlanRows} chapter_revision_plan_record WHERE book_id=(SELECT book_id FROM ${chapterRevisionPreviewRows} chapter_revision_preview_record WHERE id=$1) AND idempotency_key=$2`,[previewId,input.idempotencyKey])).rows[0];if(prior){await assertRevisionOriginal(pool,'chapter_revision_plan',String(prior.id),{previewId,...input,createdBy:input.createdBy??'user'});return getChapterRevisionWorkspace(previewId);}const existing=(await pool.query(`SELECT id FROM ${chapterRevisionPlanRows} chapter_revision_plan_record WHERE preview_id=$1`,[previewId])).rows[0];if(existing){await assertRevisionOriginal(pool,'chapter_revision_plan',String(existing.id),{previewId,...input,createdBy:input.createdBy??'user'});return getChapterRevisionWorkspace(previewId);}
  const client=await pool.connect(),planId=randomUUID(),actor=input.createdBy??"user";let committing=false;try{await client.query("BEGIN");await lockStoryRecords(client);await requireCardWorkflowTypes(client,['chapter_revision_preview','chapter_revision_plan','chapter_revision_execution','chapter_revision_event'],true);const repeated=await readRevisionOriginal(client,'chapter_revision_plan','chapter_revision_preview',previewId,{previewId,...input,createdBy:actor});if(repeated){await client.query('ROLLBACK');return getChapterRevisionWorkspace(previewId);}const preview=assertFound((await client.query(`SELECT * FROM ${chapterRevisionPreviewRows} chapter_revision_preview_record WHERE id=$1 FOR UPDATE`,[previewId])).rows[0],"影响预览不存在。");if(preview.status!=="ready"||Number(preview.revision)!==input.expectedPreviewRevision||Number(preview.expected_document_revision)!==input.expectedDocumentRevision)throw new NewDesignError("影响预览或章节修订已变化，请重新生成。",409);const impacts=(await client.query(`SELECT * FROM ${chapterRevisionImpactRows} chapter_revision_impact_record WHERE preview_id=$1 ORDER BY sequence FOR UPDATE`,[previewId])).rows,choices=new Map(input.items.map(item=>[item.impactId,item])),summary:Record<string,number>={},resolved:Array<{impact:Row;choice:typeof input.items[number]|undefined;action:ChapterRevisionAction}>=[];if(choices.size!==input.items.length||input.items.some(item=>!impacts.some(impact=>String(impact.id)===item.impactId)))throw new NewDesignError('换稿计划包含重复或非本次预览的影响项。',422);for(const impact of impacts){const choice=choices.get(String(impact.id)),action=(choice?.selectedAction??impact.recommended_action) as ChapterRevisionAction;if(!(impact.allowed_actions as string[]).includes(action))throw new NewDesignError(`“${(impact.detail as Row)?.title??impact.target_kind}”不支持所选处理方式。`,422);if(["high","critical"].includes(String(impact.risk_level))&&action==="defer")throw new NewDesignError("高风险影响不能暂不处理。",422);summary[action]=(summary[action]??0)+1;resolved.push({impact,choice,action});}
    await insertRevisionRecords(client, 'chapter_revision_plan', `SELECT ($1)::uuid AS id,($2)::uuid AS preview_id,($3)::uuid AS book_id,($4)::integer AS expected_preview_revision,($5)::integer AS expected_document_revision,($6)::text AS reason,('draft')::text AS status,($7::jsonb)::jsonb AS summary,(1)::integer AS revision,($8)::text AS idempotency_key,($9)::text AS created_by,(NULL)::text AS confirmed_by,(NULL)::timestamptz AS confirmed_at,(now())::timestamptz AS created_at,(now())::timestamptz AS updated_at, ($10::jsonb)::jsonb AS request_input,($11)::text AS request_hash`, [planId,previewId,preview.book_id,input.expectedPreviewRevision,input.expectedDocumentRevision,input.reason,json(summary),input.idempotencyKey,actor,json({previewId,...input,createdBy:actor}),stableHash({previewId,...input,createdBy:actor})], [["id"],["preview_id"],["book_id","idempotency_key"]]);
    for(const {impact,choice,action} of resolved)await insertRevisionRecords(client, 'chapter_revision_plan_item', `SELECT ($1)::uuid AS id,($2)::uuid AS plan_id,($3)::uuid AS impact_id,($4)::text AS selected_action,($5)::text AS decision_source,($6)::text AS note,(1)::integer AS revision,($7)::text AS decided_by,(now())::timestamptz AS created_at,(now())::timestamptz AS updated_at`, [randomUUID(),planId,impact.id,action,choice?"user":"default",choice?.note??"",actor], [["id"],["plan_id","impact_id"]]);
    await insertRevisionRecords(client, 'chapter_revision_event', `SELECT ($1)::uuid AS id,($2)::uuid AS preview_id,($3)::uuid AS plan_id,(NULL)::uuid AS execution_id,('plan_saved')::text AS event_kind,($4)::text AS actor,($5)::text AS idempotency_key,($6::jsonb)::jsonb AS detail,(now())::timestamptz AS created_at`, [randomUUID(),previewId,planId,actor,input.idempotencyKey,json({summary})], [["id"]]);committing=true;await client.query("COMMIT");return getChapterRevisionWorkspace(previewId);
  }catch(error){throw await revisionFailure(client,error,committing);}finally{client.release();}
}

async function protect(client:PoolClient,bookId:string,kind:string,id:string,executionId:string,reason:string,actor:string){await insertRevisionRecords(client, 'chapter_revision_protection_mark', `SELECT ($1)::uuid AS id,($2)::uuid AS book_id,($3)::text AS target_kind,($4)::uuid AS target_id,('manual_correction')::text AS protection_kind,($5)::uuid AS source_execution_id,($6)::text AS reason,($7)::text AS actor,(now())::timestamptz AS created_at`, [randomUUID(),bookId,kind,id,executionId,reason,actor], [["id"],["book_id","target_kind","target_id","protection_kind"]], {"ignore":true,"keys":["book_id","target_kind","target_id","protection_kind"]});}
async function cancelGeneratedRequest(client:PoolClient,eventId:string,resourceId:string){const requests=await updateRevisionRecords(client, 'dependency_recompute_request', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('cancelled')::text,'completed_at',(now())::timestamptz) AS record_patch FROM ${dependencyRecomputeRequestRows} record WHERE invalidation_event_id=$1 AND target_resource_id=$2 AND status='pending' FOR UPDATE OF record`, [eventId,resourceId], ["id"]);for(const row of requests.rows)await client.query("UPDATE new_design.background_jobs SET status='cancelled',last_error_kind='cancelled',last_error_code='revision_plan',last_error_summary='按换稿处理计划保留人工复核。',revision=revision+1,updated_at=now(),completed_at=now() WHERE specialized_request_kind='dependency_recompute_request' AND specialized_request_id=$1 AND status='queued'",[row.id]);}
async function invalidateKnowledgeChange(client:PoolClient,changeId:string,executionId:string,actor:string){const change=assertFound((await updateRevisionRecords(client, 'knowledge_state_change', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('invalidated')::text) AS record_patch FROM ${knowledgeStateChangeRows} record WHERE id=$1 AND status='active' FOR UPDATE OF record`, [changeId], ["id"])).rows[0],"角色所知变化已由其他操作处理，请重新生成影响预览。");await updateRevisionRecords(client, 'knowledge_state_proposal', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('invalidated')::text,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz) AS record_patch FROM ${knowledgeStateProposalRows} record WHERE id=$1 AND status='confirmed' FOR UPDATE OF record`, [change.proposal_id], ["id"]);await insertStoryReviewActions(client, 'knowledge_state', `SELECT ($1)::uuid AS id,($2)::uuid AS proposal_id,($3)::uuid AS proposal_version_id,('invalidate')::text AS action,($4)::text AS actor,($5)::text AS note,($6)::text AS idempotency_key,(now())::timestamptz AS created_at`, [randomUUID(),change.proposal_id,change.proposal_version_id,actor,"旧章正文被替换，原角色所知来源失效。",`f5:knowledge:${executionId}:${changeId}`]);const prior=(await client.query(`SELECT * FROM ${knowledgeStateChangeRows} knowledge_state_change_record WHERE book_id=$1 AND holder_kind=$2 AND holder_key=$3 AND claim_id=$4 AND status='active' ORDER BY effective_narrative_order DESC NULLS LAST,sequence DESC LIMIT 1`,[change.book_id,change.holder_kind,change.holder_key,change.claim_id])).rows[0];if(!prior){await deleteRevisionRecords(client, 'current_knowledge_state_projection', `SELECT to_jsonb(record) AS record_values FROM ${currentKnowledgeStateProjectionRows} record WHERE book_id=$1 AND holder_kind=$2 AND holder_key=$3 AND claim_id=$4 FOR UPDATE OF record`, [change.book_id,change.holder_kind,change.holder_key,change.claim_id], ["book_id","holder_kind","holder_key","claim_id"]);return;}await insertRevisionRecords(client, 'current_knowledge_state_projection', `SELECT ($1)::uuid AS book_id,($2)::text AS holder_kind,($3)::text AS holder_key,($4)::uuid AS holder_card_id,($5)::uuid AS claim_id,($6)::uuid AS source_change_id,($7)::text AS stance,($8)::numeric AS confidence,($9)::numeric AS effective_story_order,($10)::numeric AS effective_narrative_order,(1)::bigint AS projection_revision,(now())::timestamptz AS rebuilt_at`, [prior.book_id,prior.holder_kind,prior.holder_key,prior.holder_card_id,prior.claim_id,prior.id,prior.stance,prior.confidence,prior.effective_story_order,prior.effective_narrative_order], [["book_id","holder_kind","holder_key","claim_id"]], {keys:["book_id","holder_kind","holder_key","claim_id"],update:(previous:Record<string,any>,incoming:Record<string,any>)=>({holder_card_id:incoming.holder_card_id,source_change_id:incoming.source_change_id,stance:incoming.stance,confidence:incoming.confidence,effective_story_order:incoming.effective_story_order,effective_narrative_order:incoming.effective_narrative_order,projection_revision:Number(previous.projection_revision)+1,rebuilt_at:new Date().toISOString()})});}

export async function executeChapterRevisionPlan(planId:string,input:{expectedPlanRevision:number;expectedPreviewRevision:number;expectedDocumentRevision:number;idempotencyKey:string;actor?:string;confirmed:boolean}):Promise<ChapterRevisionWorkspace>{
  if(!input.confirmed)throw new NewDesignError("请确认换稿范围和处理数量后再执行。",422);const pool=await getNewDesignPool(),existing=(await pool.query(`SELECT id,preview_id FROM ${chapterRevisionExecutionRows} chapter_revision_execution_record WHERE plan_id=$1 OR (book_id=(SELECT book_id FROM ${chapterRevisionPlanRows} chapter_revision_plan_record WHERE id=$1) AND idempotency_key=$2) ORDER BY created_at DESC LIMIT 1`,[planId,input.idempotencyKey])).rows[0];if(existing){await assertRevisionOriginal(pool,'chapter_revision_execution',String(existing.id),{planId,...input,actor:input.actor??'user'});return getChapterRevisionWorkspace(String(existing.preview_id));}
  const client=await pool.connect(),executionId=randomUUID(),adoptionId=randomUUID(),actor=input.actor??"user";let expired=false,previewId="";
  let committing=false;try{await client.query("BEGIN");await lockStoryRecords(client);await requireCardWorkflowTypes(client,['chapter_revision_preview','chapter_revision_plan','chapter_revision_execution','chapter_revision_event'],true);const repeated=await readRevisionOriginal(client,'chapter_revision_execution','chapter_revision_plan',planId,{planId,...input,actor});if(repeated){await client.query('ROLLBACK');return getChapterRevisionWorkspace(String(repeated.preview_id));}const plan=assertFound((await client.query(`SELECT * FROM ${chapterRevisionPlanRows} chapter_revision_plan_record WHERE id=$1 FOR UPDATE`,[planId])).rows[0],"换稿处理计划不存在。"),preview=assertFound((await client.query(`SELECT * FROM ${chapterRevisionPreviewRows} chapter_revision_preview_record WHERE id=$1 FOR UPDATE`,[plan.preview_id])).rows[0],"影响预览不存在。"),document=assertFound((await client.query("SELECT * FROM new_design.chapter_documents WHERE id=$1 FOR UPDATE",[preview.chapter_document_id])).rows[0],"章节正文档案不存在。");previewId=String(preview.id);if(plan.status!=="draft"||Number(plan.revision)!==input.expectedPlanRevision||preview.status!=="ready"||Number(preview.revision)!==input.expectedPreviewRevision||Number(plan.expected_document_revision)!==input.expectedDocumentRevision||Number(preview.expected_document_revision)!==input.expectedDocumentRevision)throw new NewDesignError("处理计划、影响预览或章节修订已变化，请刷新后重试。",409);if(Number(document.revision)!==input.expectedDocumentRevision||String(document.adopted_version_id)!==String(preview.old_body_version_id)){expired=true;}else{const frozen=(preview.dependency_generation??[]) as Array<{id:string}>,current=frozen.length?await client.query(`SELECT resource.id,resource.resource_kind,resource.stable_object_id,resource.exact_version_id,resource.content_hash,COALESCE(state.revision,0) state_revision,COALESCE(state.state,'fresh') state FROM new_design.dependency_resources resource LEFT JOIN ${dependencyResourceStateRows} state ON state.resource_id=resource.id WHERE resource.id=ANY($1::uuid[]) ORDER BY resource.id`,[frozen.map(item=>item.id)]):{rows:[]},normalized=current.rows.map(row=>({id:String(row.id),resourceKind:String(row.resource_kind),stableObjectId:String(row.stable_object_id),exactVersionId:String(row.exact_version_id),contentHash:String(row.content_hash),stateRevision:Number(row.state_revision),state:String(row.state),depth:Number((frozen.find(item=>item.id===String(row.id)) as Row|undefined)?.depth??0)}));if(stableHash(normalized)!==stableHash(frozen))expired=true;}
    if(expired){await updateRevisionRecords(client, 'chapter_revision_preview', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('expired')::text,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz) AS record_patch FROM ${chapterRevisionPreviewRows} record WHERE id=$1 FOR UPDATE OF record`, [preview.id], ["id"]);await insertRevisionRecords(client, 'chapter_revision_event', `SELECT ($1)::uuid AS id,($2)::uuid AS preview_id,($3)::uuid AS plan_id,(NULL)::uuid AS execution_id,('preview_expired')::text AS event_kind,($4)::text AS actor,(NULL)::text AS idempotency_key,($5::jsonb)::jsonb AS detail,(now())::timestamptz AS created_at`, [randomUUID(),preview.id,planId,actor,json({reason:"document_or_dependency_generation_changed"})], [["id"]]);committing=true;await client.query("COMMIT");}else{
      await updateRevisionRecords(client, 'chapter_revision_plan', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('confirmed')::text,'confirmed_by',($2)::text,'confirmed_at',(now())::timestamptz,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz) AS record_patch FROM ${chapterRevisionPlanRows} record WHERE id=$1 FOR UPDATE OF record`, [planId,actor], ["id"]);
      const nextRevision=Number(document.revision)+1;await client.query("UPDATE new_design.chapter_documents SET adopted_version_id=$2,revision=$3,updated_at=now() WHERE id=$1",[document.id,preview.new_body_version_id,nextRevision]);await client.query("INSERT INTO new_design.chapter_body_adoptions(id,chapter_document_id,from_version_id,to_version_id,action,document_revision,idempotency_key,actor) VALUES($1,$2,$3,$4,'readopt',$5,$6,$7)",[adoptionId,document.id,preview.old_body_version_id,preview.new_body_version_id,nextRevision,`f5:${input.idempotencyKey}`,actor]);
      const oldResource=await registerResource(client,"chapter_body_version",String(document.id),String(preview.old_body_version_id)),newResource=await registerResource(client,"chapter_body_version",String(document.id),String(preview.new_body_version_id));let invalidation=(await client.query(`SELECT id FROM ${dependencyInvalidationEventRows} dependency_invalidation_event_record WHERE trigger_id=$1 ORDER BY created_at DESC LIMIT 1`,[adoptionId])).rows[0];if(!invalidation){const eventId=randomUUID();await client.query("SELECT new_design.record_dependency_invalidation($1,$2,$3,$4,$5,'body_adoption','stale',$6,$7)",[eventId,preview.book_id,oldResource,newResource,"旧章采用正文切换。",adoptionId,`chapter-revision:${executionId}`]);invalidation={id:eventId};}
      await updateRevisionRecords(client, 'chapter_stable_checkpoint', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('superseded')::text) AS record_patch FROM ${chapterStableCheckpointRows} record WHERE id=$1 FOR UPDATE OF record`, [preview.old_checkpoint_id], ["id"]);await client.query("UPDATE new_design.chapter_settlements SET status='superseded',revision=revision+1 WHERE id=$1 AND status='committed'",[preview.old_settlement_id]);await updateRevisionRecords(client, 'chapter_adoption_preparation', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('consumed')::text) AS record_patch FROM ${chapterAdoptionPreparationRows} record WHERE id=(SELECT preparation_id FROM ${chapterAdoptionSessionRows} chapter_adoption_session_record WHERE id=$1) FOR UPDATE OF record`, [preview.session_id], ["id"]);await updateRevisionRecords(client, 'chapter_adoption_session', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('adoption_id',($2)::uuid,'status',('adopted_pending_proposals')::text,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz) AS record_patch FROM ${chapterAdoptionSessionRows} record WHERE id=$1 FOR UPDATE OF record`, [preview.session_id,adoptionId], ["id"]);
      await insertRevisionRecords(client, 'chapter_revision_execution', `SELECT ($1)::uuid AS id,($2)::uuid AS plan_id,($3)::uuid AS preview_id,($4)::uuid AS book_id,($5)::uuid AS chapter_document_id,($6)::uuid AS old_body_version_id,($7)::uuid AS new_body_version_id,($8)::uuid AS old_checkpoint_id,($9)::uuid AS restart_checkpoint_id,($10)::uuid AS adoption_id,($11)::uuid AS invalidation_event_id,('queued')::text AS status,(0)::integer AS current_step,(0)::integer AS total_steps,(1)::integer AS revision,($12)::text AS idempotency_key,($13)::text AS actor,('')::text AS error_summary,(now())::timestamptz AS created_at,(now())::timestamptz AS updated_at,(NULL)::timestamptz AS completed_at, ($14::jsonb)::jsonb AS request_input,($15)::text AS request_hash`, [executionId,planId,preview.id,preview.book_id,document.id,preview.old_body_version_id,preview.new_body_version_id,preview.old_checkpoint_id,preview.restart_checkpoint_id,adoptionId,invalidation.id,input.idempotencyKey,actor,json({planId,...input,actor}),stableHash({planId,...input,actor})], [["id"],["plan_id"],["preview_id"],["adoption_id"],["book_id","idempotency_key"]]);
      const items=(await client.query(`SELECT item.*,impact.category,impact.target_kind,impact.target_id,impact.target_version_id,impact.target_chapter_document_id,impact.target_chapter_order,impact.source_mode,impact.risk_level,impact.reason_chain,impact.detail FROM ${chapterRevisionPlanItemRows} item JOIN ${chapterRevisionImpactRows} impact ON impact.id=item.impact_id WHERE item.plan_id=$1 ORDER BY impact.sequence`,[planId])).rows;let sequence=0,previousStep:string|null=null,reviewCount=0;
      const addStep=async(item:Row,kind:ChapterRevisionExecution["steps"][number]["stepKind"],status:ChapterRevisionExecution["steps"][number]["status"],requestId:string|null=null,jobId:string|null=null)=>{const id=randomUUID();await insertRevisionRecords(client, 'chapter_revision_recompute_step', `SELECT ($1)::uuid AS id,($2)::uuid AS execution_id,($3)::integer AS sequence,($4)::uuid AS predecessor_step_id,($5)::uuid AS impact_id,($6)::uuid AS chapter_document_id,($7)::integer AS chapter_order,($8)::text AS step_kind,($9)::text AS selected_action,($10)::uuid AS dependency_request_id,($11)::uuid AS background_job_id,($12)::text AS status,('{}'::jsonb)::jsonb AS result,('')::text AS error_summary,($13)::text AS idempotency_key,(now())::timestamptz AS created_at,(now())::timestamptz AS updated_at,(CASE WHEN $12 IN ('succeeded','skipped','review_required') THEN now() END)::timestamptz AS completed_at`, [id,executionId,++sequence,previousStep,item.impact_id,item.target_chapter_document_id,item.target_chapter_order,kind,item.selected_action,requestId,jobId,status,`step:${executionId}:${sequence}`], [["id"],["execution_id","sequence"],["execution_id","idempotency_key"]]);previousStep=id;};
      await addStep({impact_id:null,target_chapter_document_id:document.id,target_chapter_order:document.logical_order,selected_action:"mark_stale"},"invalidate_source","succeeded");
      let protectedCurrent=false,currentReview=false;
      for(const item of items){const action=item.selected_action as ChapterRevisionAction,detail=(item.detail??{}) as Row,targetId=String(item.target_id);
        if(action==="review_manually")currentReview=true;
        if(item.target_kind==="canonical_fact"){await updateRevisionRecords(client, 'canonical_fact_evidence', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('stale_at',(now())::timestamptz,'stale_reason',('来源正文被替换。')::text) AS record_patch FROM ${canonicalFactEvidenceRows} record WHERE id=$1 AND stale_at IS NULL FOR UPDATE OF record`, [detail.evidenceId], ["id"]);if(action==="keep_manual_correction"){await protect(client,String(preview.book_id),"canonical_fact",targetId,executionId,item.note||"作者在换稿时明确保留。",actor);protectedCurrent=true;}else{const remaining=Number((await client.query(`SELECT count(*) value FROM ${canonicalFactEvidenceRows} canonical_fact_evidence_record WHERE fact_id=$1 AND stale_at IS NULL`,[targetId])).rows[0].value);if(remaining===0){await updateRevisionRecords(client, 'canonical_fact', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('stale')::text,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz) AS record_patch FROM ${canonicalFactRows} record WHERE id=$1 AND status='confirmed' FOR UPDATE OF record`, [targetId], ["id"]);await insertStoryReviewActions(client, 'canonical_fact', `SELECT ($1)::uuid AS id,($2)::uuid AS fact_id,('mark_stale')::text AS action,('confirmed')::text AS from_status,('stale')::text AS to_status,($5)::text AS idempotency_key,($3)::text AS actor,($4)::text AS note,(now())::timestamptz AS created_at`, [randomUUID(),targetId,actor,"来源正文被替换。",`f5:${executionId}:${targetId}`]);}}}
        else if(item.target_kind==="knowledge_state_change"){if(action==="keep_manual_correction"){await protect(client,String(preview.book_id),"knowledge_state_change",targetId,executionId,item.note||"作者在换稿时明确保留。",actor);protectedCurrent=true;}else await invalidateKnowledgeChange(client,targetId,executionId,actor);}
        else if(item.target_kind==="state_change"){if(action==="keep_manual_correction"){await protect(client,String(preview.book_id),"state_change",targetId,executionId,item.note||"作者在换稿时明确保留。",actor);protectedCurrent=true;}else{await updateRevisionRecords(client, 'state_change', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('invalidated')::text) AS record_patch FROM ${stateChangeRows} record WHERE id=$1 AND status='active' FOR UPDATE OF record`, [targetId], ["id"]);await updateRevisionRecords(client, 'state_change_proposal', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('invalidated')::text,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz) AS record_patch FROM ${stateChangeProposalRows} record WHERE confirmed_state_change_id=$1 AND status='confirmed' FOR UPDATE OF record`, [targetId], ["id"]);await updateRevisionRecords(client, 'current_state_projection', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('is_stale',(true)::boolean,'projection_revision',(projection_revision+1)::bigint,'rebuilt_at',(now())::timestamptz) AS record_patch FROM ${currentStateProjectionRows} record WHERE source_state_change_id=$1 FOR UPDATE OF record`, [targetId], ["book_id","subject_kind","subject_id","state_key"]);}}
        else if(item.target_kind==="chapter_body"){reviewCount++;await insertRevisionRecords(client, 'chapter_revision_review_flag', `SELECT ($1)::uuid AS id,($2)::uuid AS book_id,($3)::uuid AS execution_id,($4)::uuid AS changed_chapter_document_id,($5)::uuid AS target_chapter_document_id,($6)::uuid AS target_body_version_id,($7)::uuid AS impact_id,('pending_review')::text AS status,($8)::text AS reason,($9)::text AS source_route,(false)::boolean AS manual_protected,('')::text AS resolution_note,(1)::integer AS revision,(now())::timestamptz AS created_at,(now())::timestamptz AS updated_at,(NULL)::timestamptz AS resolved_at`, [randomUUID(),preview.book_id,executionId,document.id,item.target_chapter_document_id,item.target_version_id,item.impact_id,(item.reason_chain??["上游章节正文已切换。"]).join(" → "),`/new-design/books/${preview.book_id}/writing?chapterDocument=${item.target_chapter_document_id}&revisionExecution=${executionId}`], [["id"],["execution_id","target_chapter_document_id"]]);await addStep(item,"review_body","review_required");}
        else if(item.target_kind==="dependency_resource"){const request=(await client.query(`SELECT request.id,job.id job_id FROM ${dependencyRecomputeRequestRows} request LEFT JOIN new_design.background_jobs job ON job.specialized_request_kind='dependency_recompute_request' AND job.specialized_request_id=request.id WHERE request.invalidation_event_id=$1 AND request.target_resource_id=$2 ORDER BY request.created_at DESC LIMIT 1`,[invalidation.id,targetId])).rows[0];if(action==="auto_recompute"&&request)await addStep(item,"recompute_chapter","queued",String(request.id),nullable(request.job_id));else{await cancelGeneratedRequest(client,String(invalidation.id),targetId);await addStep(item,"recompute_chapter",action==="review_manually"?"review_required":"skipped");}}
      }
      if(protectedCurrent||currentReview){reviewCount++;await insertRevisionRecords(client, 'chapter_revision_review_flag', `SELECT ($1)::uuid AS id,($2)::uuid AS book_id,($3)::uuid AS execution_id,($4)::uuid AS changed_chapter_document_id,($4)::uuid AS target_chapter_document_id,($5)::uuid AS target_body_version_id,(NULL)::uuid AS impact_id,('pending_review')::text AS status,($6)::text AS reason,($7)::text AS source_route,($8)::boolean AS manual_protected,('')::text AS resolution_note,(1)::integer AS revision,(now())::timestamptz AS created_at,(now())::timestamptz AS updated_at,(NULL)::timestamptz AS resolved_at`, [randomUUID(),preview.book_id,executionId,document.id,preview.new_body_version_id,protectedCurrent?"本章保留了人工纠正，需要与新正文共同复核。":"本章存在选择人工复核的换稿影响。",`/new-design/books/${preview.book_id}/writing?chapterDocument=${document.id}&revisionExecution=${executionId}`,protectedCurrent], [["id"],["execution_id","target_chapter_document_id"]], {"ignore":true,"keys":["execution_id","target_chapter_document_id"]});}
      await addStep({impact_id:null,target_chapter_document_id:null,target_chapter_order:null,selected_action:"auto_recompute"},"rebuild_graph","queued");await addStep({impact_id:null,target_chapter_document_id:null,target_chapter_order:null,selected_action:"auto_recompute"},"rebuild_semantic","queued");
      await updateRevisionRecords(client, 'chapter_revision_execution', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('running')::text,'total_steps',($2)::integer,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz) AS record_patch FROM ${chapterRevisionExecutionRows} record WHERE id=$1 FOR UPDATE OF record`, [executionId,sequence], ["id"]);await updateRevisionRecords(client, 'chapter_revision_execution', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('awaiting_review')::text,'current_step',(1)::integer,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz) AS record_patch FROM ${chapterRevisionExecutionRows} record WHERE id=$1 FOR UPDATE OF record`, [executionId], ["id"]);await updateRevisionRecords(client, 'chapter_revision_plan', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('executing')::text,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz) AS record_patch FROM ${chapterRevisionPlanRows} record WHERE id=$1 FOR UPDATE OF record`, [planId], ["id"]);await updateRevisionRecords(client, 'chapter_revision_preview', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',('consumed')::text,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz) AS record_patch FROM ${chapterRevisionPreviewRows} record WHERE id=$1 FOR UPDATE OF record`, [preview.id], ["id"]);await insertRevisionRecords(client, 'chapter_revision_event', `SELECT ($1)::uuid AS id,($2)::uuid AS preview_id,($3)::uuid AS plan_id,($4)::uuid AS execution_id,('execution_confirmed')::text AS event_kind,($5)::text AS actor,($6)::text AS idempotency_key,($7::jsonb)::jsonb AS detail,(now())::timestamptz AS created_at`, [randomUUID(),preview.id,planId,executionId,actor,input.idempotencyKey,json({documentRevision:nextRevision,reviewCount,totalSteps:sequence,restartCheckpointId:preview.restart_checkpoint_id})], [["id"]]);committing=true;await client.query("COMMIT");
    }
  }catch(error){throw await revisionFailure(client,error,committing);}finally{client.release();}
  if(expired)throw new NewDesignError("正文、稳定检查点或依赖来源已变化，请重新生成影响预览。",409);return getChapterRevisionWorkspace(previewId);
}

export async function resolveChapterRevisionReviewFlag(flagId:string,input:{expectedRevision:number;resolution:"resolved"|"retained"|"cancelled";note:string;actor?:string}):Promise<ChapterRevisionWorkspace>{const pool=await getNewDesignPool(),client=await pool.connect(),actor=input.actor??"user";let committing=false;try{await client.query("BEGIN");await lockStoryRecords(client);await requireCardWorkflowTypes(client,['chapter_revision_preview','chapter_revision_plan','chapter_revision_execution','chapter_revision_event'],true);const flag=assertFound((await client.query(`SELECT * FROM ${chapterRevisionReviewFlagRows} chapter_revision_review_flag_record WHERE id=$1 FOR UPDATE`,[flagId])).rows[0],"待复核章节不存在。");if(Number(flag.revision)!==input.expectedRevision||!["pending_review","in_review"].includes(String(flag.status)))throw new NewDesignError("复核状态已变化，请刷新后重试。",409);await updateRevisionRecords(client, 'chapter_revision_review_flag', `SELECT to_jsonb(record) AS record_values,jsonb_build_object('status',($2)::text,'resolution_note',($3)::text,'revision',(revision+1)::integer,'updated_at',(now())::timestamptz,'resolved_at',(now())::timestamptz) AS record_patch FROM ${chapterRevisionReviewFlagRows} record WHERE id=$1 FOR UPDATE OF record`, [flagId,input.resolution,input.note], ["id"]);const execution=assertFound((await client.query(`SELECT * FROM ${chapterRevisionExecutionRows} chapter_revision_execution_record WHERE id=$1`,[flag.execution_id])).rows[0],"换稿执行记录不存在。");await insertRevisionRecords(client, 'chapter_revision_event', `SELECT ($1)::uuid AS id,($2)::uuid AS preview_id,($3)::uuid AS plan_id,($4)::uuid AS execution_id,('review_resolved')::text AS event_kind,($5)::text AS actor,(NULL)::text AS idempotency_key,($6::jsonb)::jsonb AS detail,(now())::timestamptz AS created_at`, [randomUUID(),execution.preview_id,execution.plan_id,execution.id,actor,json({flagId,resolution:input.resolution,note:input.note})], [["id"]]);committing=true;await client.query("COMMIT");return getChapterRevisionWorkspace(String(execution.preview_id));}catch(error){throw await revisionFailure(client,error,committing);}finally{client.release();}}

export async function getChapterRevisionWorkspace(previewId:string):Promise<ChapterRevisionWorkspace>{const pool=await getNewDesignPool(),previewRow=assertFound((await pool.query(`SELECT * FROM ${chapterRevisionPreviewRows} chapter_revision_preview_record WHERE id=$1`,[previewId])).rows[0],"影响预览不存在。"),preview=mapPreview(previewRow),document=await getChapterDocument(preview.chapterDocumentId),oldBody=assertFound(document.versions.find(item=>item.id===preview.oldBodyVersionId),"旧正文版本不存在。"),newBody=assertFound(document.versions.find(item=>item.id===preview.newBodyVersionId),"候选正文版本不存在。"),impacts=(await pool.query(`SELECT * FROM ${chapterRevisionImpactRows} chapter_revision_impact_record WHERE preview_id=$1 ORDER BY sequence`,[previewId])).rows.map(mapImpact),planRow=(await pool.query(`SELECT * FROM ${chapterRevisionPlanRows} chapter_revision_plan_record WHERE preview_id=$1`,[previewId])).rows[0],planItems=planRow?(await pool.query(`SELECT * FROM ${chapterRevisionPlanItemRows} chapter_revision_plan_item_record WHERE plan_id=$1 ORDER BY created_at,id`,[planRow.id])).rows:[],executionRow=(await pool.query(`SELECT * FROM ${chapterRevisionExecutionRows} chapter_revision_execution_record WHERE preview_id=$1`,[previewId])).rows[0],steps=executionRow?(await pool.query(`SELECT step.*,job.status job_status FROM ${chapterRevisionRecomputeStepRows} step LEFT JOIN new_design.background_jobs job ON job.id=step.background_job_id WHERE step.execution_id=$1 ORDER BY step.sequence`,[executionRow.id])).rows:[],plan=planRow?mapPlan(planRow,planItems):null,execution=executionRow?mapExecution(executionRow,steps):null,actions=plan?.items.map(item=>item.selectedAction)??impacts.map(item=>item.recommendedAction),highRiskUnresolved=plan?0:impacts.filter(item=>["high","critical"].includes(item.riskLevel)).length;return{preview,oldBody,newBody,impacts,plan,execution,confirmation:{pointerMoves:true,invalidateCount:actions.filter(item=>item==="auto_recompute"||item==="mark_stale").length,preserveCount:actions.filter(item=>item==="keep_manual_correction").length,reviewCount:actions.filter(item=>item==="review_manually").length,recomputeCount:actions.filter(item=>item==="auto_recompute").length,highRiskUnresolved},updatedAt:new Date().toISOString()};}

export async function getChapterRevisionStableReadContract(bookId:string,chapterDocumentId?:string|null):Promise<ChapterRevisionStableReadContract>{const pool=await getNewDesignPool(),flags=await pool.query(`SELECT flag.*,execution.id execution_id FROM ${chapterRevisionReviewFlagRows} flag JOIN ${chapterRevisionExecutionRows} execution ON execution.id=flag.execution_id WHERE flag.book_id=$1 AND flag.status IN ('pending_review','in_review') AND ($2::uuid IS NULL OR flag.target_chapter_document_id=$2) ORDER BY flag.updated_at DESC,flag.id`,[bookId,chapterDocumentId??null]),executions=await pool.query(`SELECT * FROM ${chapterRevisionExecutionRows} chapter_revision_execution_record WHERE book_id=$1 AND status NOT IN ('stable','cancelled') AND ($2::uuid IS NULL OR chapter_document_id=$2) ORDER BY updated_at DESC,id`,[bookId,chapterDocumentId??null]),checkpoint=chapterDocumentId?(await pool.query(`SELECT * FROM ${chapterStableCheckpointRows} chapter_stable_checkpoint_record WHERE book_id=$1 AND chapter_document_id=$2 AND status='stable' ORDER BY created_at DESC LIMIT 1`,[bookId,chapterDocumentId])).rows[0]:(await pool.query(`SELECT * FROM ${chapterStableCheckpointRows} chapter_stable_checkpoint_record WHERE book_id=$1 AND status='stable' ORDER BY chapter_order DESC,created_at DESC LIMIT 1`,[bookId])).rows[0];return{bookId,chapterDocumentId:chapterDocumentId??null,currentImpacts:flags.rows.map(row=>({id:String(row.id),revision:Number(row.revision),executionId:String(row.execution_id),changedChapterDocumentId:String(row.changed_chapter_document_id),targetChapterDocumentId:String(row.target_chapter_document_id),targetBodyVersionId:nullable(row.target_body_version_id),status:String(row.status),reason:String(row.reason),sourceRoute:String(row.source_route),manualProtected:Boolean(row.manual_protected),updatedAt:iso(row.updated_at)})),executions:executions.rows.map(row=>({id:String(row.id),chapterDocumentId:String(row.chapter_document_id),oldBodyVersionId:String(row.old_body_version_id),newBodyVersionId:String(row.new_body_version_id),status:String(row.status),currentStep:Number(row.current_step),totalSteps:Number(row.total_steps),updatedAt:iso(row.updated_at)})),safeCheckpoint:checkpoint?mapCheckpoint(checkpoint):null,generatedAt:new Date().toISOString()};}
